# Let's verify all properties rigorously

import itertools

# Reconstruct the graph
n = 20
parts = []
for i in range(6):
    parts.append(list(range(3*i, 3*i+3)))
parts.append([18, 19])

adj = [[False]*n for _ in range(n)]
edges = []
for i, part_i in enumerate(parts):
    for j, part_j in enumerate(parts):
        if i < j:
            for u in part_i:
                for v in part_j:
                    a, b = min(u,v), max(u,v)
                    adj[a][b] = True
                    adj[b][a] = True
                    edges.append((a,b))

edges = sorted(set(edges))

# 1. Verify independence number <= 3
# Check all 4-subsets
print("Checking independence number...")
found_indep_4 = False
for subset in itertools.combinations(range(n), 4):
    is_indep = True
    for u, v in itertools.combinations(subset, 2):
        if adj[u][v]:
            is_indep = False
            break
    if is_indep:
        found_indep_4 = True
        print(f"Found independent set of size 4: {subset}")
        break

if not found_indep_4:
    print("✓ No independent set of size 4 found. alpha(G) <= 3.")

# 2. Verify vertex connectivity >= 4
# For complete multipartite, connectivity = min degree
degrees = [sum(adj[v]) for v in range(n)]
print(f"\nDegree sequence: min={min(degrees)}, max={max(degrees)}")
print(f"Degrees: {degrees}")

# For complete multipartite graphs, κ(G) = δ(G) (min degree)
# This is a known theorem. Let's also verify by checking that 
# removing any 3 vertices leaves the graph connected.

def is_connected(adj_matrix, vertices):
    if not vertices:
        return True
    vlist = list(vertices)
    visited = {vlist[0]}
    queue = [vlist[0]]
    while queue:
        node = queue.pop()
        for w in vlist:
            if w not in visited and adj_matrix[node][w]:
                visited.add(w)
                queue.append(w)
    return len(visited) == len(vlist)

print("\nChecking vertex connectivity >= 4...")
print("Testing all subsets of 3 vertices to remove...")
all_connected = True
for removed in itertools.combinations(range(n), 3):
    remaining = set(range(n)) - set(removed)
    if not is_connected(adj, remaining):
        all_connected = False
        print(f"Removing {removed} disconnects the graph!")
        break

if all_connected:
    print("✓ Removing any 3 vertices keeps graph connected. κ(G) >= 4.")

print(f"\nTotal edges: {len(edges)}")

print("Final edge list:")
for e in edges:
    print(e)

